# --- figure: three states (svg) ---
def three_states():
    o = head('Висхідна, низхідна структура і діапазон')
    panels = [(20, 'Висхідна', MINT, [(0, 300), (1, 205), (2, 250), (3, 150), (4, 200), (5, 95)],
               ['', 'H', 'HL', 'HH', 'HL', 'HH']),
              (260, 'Низхідна', ROSE, [(0, 95), (1, 175), (2, 130), (3, 225), (4, 180), (5, 275)],
               ['', 'L', 'LH', 'LL', 'LH', 'LL']),
              (500, 'Діапазон', AMBER, [(0, 170), (1, 270), (2, 120), (3, 275), (4, 125), (5, 265)],
               ['', '', '', '', '', ''])]
    for x0, title, col, pts, labs in panels:
        o.append(f'<rect x="{x0}" y="16" width="200" height="348" rx="14" fill="{col}" fill-opacity=".05" stroke="{col}" stroke-opacity=".35"/>')
        o.append(text(x0 + 100, 50, title, col, 25, 'middle'))
        xs = lambda i: x0 + 22 + i * 31.2
        if title == 'Діапазон':
            o.append(f'<line x1="{x0+12}" x2="{x0+188}" y1="112" y2="112" stroke="{MOON}" stroke-dasharray="6 5" stroke-width="1.6"/>')
            o.append(f'<line x1="{x0+12}" x2="{x0+188}" y1="283" y2="283" stroke="{MOON}" stroke-dasharray="6 5" stroke-width="1.6"/>')
        pp = ' '.join(f'{xs(i):.1f},{y}' for i, y in pts)
        o.append(f'<polyline points="{pp}" fill="none" stroke="{col}" stroke-width="3" stroke-linejoin="round"/>')
        for (i, y), l in zip(pts, labs):
            o.append(f'<circle cx="{xs(i):.1f}" cy="{y}" r="4.5" fill="{col}"/>')
            if l:
                top = (l in ('H', 'HH', 'LH'))
                o.append(text(xs(i), y - 14 if top else y + 33, l, INK, 22, 'middle'))
        cap = {'Висхідна': 'вищі точки', 'Низхідна': 'нижчі точки', 'Діапазон': 'ті самі межі'}[title]
        o.append(text(x0 + 100, 350, cap, MUTED, 22, 'middle', 700))
    o.append('</svg>')
    return '\n'.join(o)

